async function api(path,options={}){if(!config)throw Error('Conecte seu projeto Supabase primeiro.');if(session&&!demo&&session.expires_at&&Date.now()/1000>session.expires_at-60){const r=await fetch(config.url+'/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{apikey:config.key,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:session.refresh_token})});const v=await r.json();if(!r.ok){session=null;localStorage.removeItem('river.session');renderLogin();throw Error('Sua sessão expirou. Entre novamente.')}session={...v,expires_at:v.expires_at||Math.floor(Date.now()/1000)+v.expires_in};localStorage.setItem('river.session',JSON.stringify(session));}const r=await fetch(config.url+path,{...options,headers:{apikey:config.key,Authorization:'Bearer '+(session?.access_token||config.key),'Content-Type':'application/json',...options.headers}});if(r.status===204)return null;const v=await r.json().catch(()=>({}));if(!r.ok)throw Error(v.msg||v.message||v.error_description||v.error||'Não foi possível concluir a operação.');return v}
async function load(){if(demo){data=read('river.demo',null)||demoSeed();user=data.profiles.find(x=>x.id===session.user.id);if(!user?.active){await logout();throw Error('Este usuário está bloqueado.')}return}const profile=await api('/rest/v1/profiles?id=eq.'+session.user.id+'&select=*');user=profile[0];if(!user?.active){await logout();throw Error('Seu acesso está bloqueado ou ainda não foi configurado.')}const tables=Object.keys(data);const results=await Promise.all(tables.map(async t=>{let rows=[],offset=0;for(;;){const batch=await api('/rest/v1/'+t+'?select=*&order=id&limit=1000&offset='+offset);rows.push(...batch);if(batch.length<1000)return rows;offset+=1000;}}));tables.forEach((t,i)=>data[t]=results[i]);}
async function put(table,record,existing=false){for(const k of ['title','name','body','description']){if(typeof record[k]==='string'&&(k!=='description'||table==='questions')&&!record[k].trim())throw Error('Preencha os campos obrigatórios.');}if(demo){const id=record.id||crypto.randomUUID();record={...record,id};if(existing){const i=data[table].findIndex(r=>r.id===id);if(i<0)throw Error('Registro não encontrado.');data[table][i]={...data[table][i],...record}}else data[table].push(record);localStorage.setItem('river.demo',JSON.stringify(data));return record}const r=await api('/rest/v1/'+table+(existing?'?id=eq.'+record.id:''),{method:existing?'PATCH':'POST',headers:{Prefer:'return=representation'},body:JSON.stringify(record)});await load();return r?.[0]}
async function remove(table,id){if(demo){data[table]=data[table].filter(x=>x.id!==id);if(table==='modules'){for(const l of data.lessons.filter(l=>l.module_id===id))await remove('lessons',l.id);data.questions.forEach(q=>{if(q.module_id===id)q.module_id=null})}if(table==='lessons')data.lesson_progress=data.lesson_progress.filter(p=>p.lesson_id!==id);if(table==='questions')data.comments=data.comments.filter(c=>c.question_id!==id);localStorage.setItem('river.demo',JSON.stringify(data))}else {await api('/rest/v1/'+table+'?id=eq.'+id,{method:'DELETE'});await load()}}
