function renderLogin(){document.title='Entrar — CPT';$('#app').innerHTML=`<div class="login"><section class="login-visual"><div class="brand"><img class="brand-badge" src="assets/cpt-badge.svg" alt="Emblema Careca Poker Team"><div class="brand-name">CPT<small>CARECA POKER TEAM</small></div></div><div class="hero-art"><div class="orbit"></div><span class="art-star">✧</span><div class="playing">A<b>♠</b><small>A</small></div><div class="playing two">K<b>♣</b><small>K</small></div><div class="art-chip"></div></div><h1>Seu próximo nível<br>começa no estudo.</h1><p>Uma biblioteca. Um time. Um espaço para transformar conhecimento em boas decisões.</p><div class="eyebrow" style="color:#d7b67e;margin-top:20px">ESTUDE · REVISE · EVOLUA</div></section><section class="login-form"><div><span class="eyebrow">BEM-VINDO À CPT</span><h1>Vamos evoluir juntos.</h1><p>Entre para acessar suas aulas e continuar seus estudos.</p><form id="loginForm" class="fields"><label>E-mail<input type="email" name="email" autocomplete="username" placeholder="seu@email.com" required></label><label>Senha<input type="password" name="password" autocomplete="current-password" placeholder="Sua senha" required></label><div id="loginError" class="error" role="alert"></div><button class="btn" type="submit">Entrar ${ico('arrow')}</button></form>${!config?'<p class="subtle" style="margin-top:15px">O login real ficará disponível após conectar o Supabase.</p>':''}<div class="demo-divider">EXPLORAR DEMONSTRAÇÃO</div><div class="demo-buttons">${btn('Como aluno','demo-student','','secondary')}${btn('Como administrador','demo-admin','','secondary')}</div><p class="subtle" style="margin:15px 0">Dados de exemplo, salvos apenas neste navegador.</p><button class="link-btn" data-action="setup">${ico('settings')} Conectar Supabase</button></div></section></div>`;$('#loginForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{if(!config)throw Error('Use a demonstração ou conecte seu projeto Supabase.');const f=new FormData(e.target);demo=false;session=null;const v=await api('/auth/v1/token?grant_type=password',{method:'POST',body:JSON.stringify({email:f.get('email'),password:f.get('password')})});session={...v,expires_at:v.expires_at||Math.floor(Date.now()/1000)+v.expires_in};localStorage.setItem('river.session',JSON.stringify(session));await load();page='dashboard';render()}catch(err){$('#loginError')&&($('#loginError').textContent=err.message)}finally{b.disabled=false}}}
